(()=>{if(document.body?.dataset.page!=='academics')return;let courseKey='',passed={};try{passed=JSON.parse(localStorage.getItem('nexzo_unit_quiz_v1')||'{}')}catch{};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function modal(){let m=document.querySelector('#nxUnitQuizModal');if(m)return m;m=document.createElement('div');m.id='nxUnitQuizModal';m.className='nx-unit-quiz-modal';m.hidden=true;m.innerHTML='<div class="nx-unit-quiz-card"><button type="button" data-close-unit-quiz>×</button><div id="nxUnitQuizBody"></div></div>';document.body.append(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-close-unit-quiz]'))m.hidden=true});return m}
function install(){document.querySelectorAll('.nx-unit').forEach((u,i)=>{if(u.querySelector('[data-unit-quiz]'))return;const b=document.createElement('button');b.type='button';b.dataset.unitQuiz=i;b.className='nx-unit-quiz-btn';b.textContent=passed[`${courseKey}:${i}`]?'✓ Passed':'Take unit quiz';u.querySelector('.nx-unit-body')?.append(b);});}
function start(unit){const body=unit.querySelector('.nx-unit-body'),topics=[...unit.querySelectorAll('.nx-topic-row>span:first-child')].map(x=>x.textContent.trim()).filter(Boolean);if(!topics.length)return;const m=modal(),q=topics.slice(0,5),index=0;let score=0;function render(){const topic=q[index%q.length],opts=[topic,...topics.filter(x=>x!==topic).slice(0,3)];opts.sort(()=>Math.random()-.5);m.querySelector('#nxUnitQuizBody').innerHTML=`<span>UNIT CHECK · ${index+1}/5</span><h2>Which topic belongs to this unit?</h2><p class="nx-quiz-topic">Choose the correct concept.</p><div class="nx-quiz-options">${opts.map(x=>`<button data-answer="${esc(x===topic)}">${esc(x)}</button>`).join('')}</div><small>Minimum 3/5 required to unlock the next unit.</small>`;m.hidden=false;m.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(b.dataset.answer==='true')score++;if(index<4){render.index=(index+1);index++;render()}else{const pass=score>=3;passed[`${courseKey}:${[...document.querySelectorAll('.nx-unit')].indexOf(unit)}`]=pass;localStorage.setItem('nexzo_unit_quiz_v1',JSON.stringify(passed));m.querySelector('#nxUnitQuizBody').innerHTML=`<h2>${pass?'Unit unlocked ✓':'Revise and retry'}</h2><p>You scored <b>${score}/5</b>. ${pass?'Next unit is now available.':'You need at least 3 correct answers.'}</p><button data-close-unit-quiz>${pass?'Continue':'Review notes and retry'}</button>`;install();}})}render()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-unit-quiz]');if(b){e.preventDefault();start(b.closest('.nx-unit'))}});const obs=new MutationObserver(install);obs.observe(document.body,{childList:true,subtree:true});window.addEventListener('nexzo:academics-course-opened',e=>{courseKey=e.detail?.courseKey||courseKey;install()});setTimeout(install,1200);
})();
